  rtol, atol = (1e-1, 1e-1) if dtype == "bfloat16" else (1e-4, 1e-4)
  gpu_value = _GetVal(use_gpu=True, dtype=dtype)
  cpu_value = _GetVal(use_gpu=False, dtype=dtype)
  self.assertAllClose(cpu_value, gpu_value, rtol=rtol, atol=atol)


