def make_batch_feature(self,
                       filenames,
                       num_epochs,
                       batch_size,
                       label_key=None,
                       reader_num_threads=1,
                       parser_num_threads=1,
                       shuffle=False,
                       shuffle_seed=None,
                       drop_final_batch=False):
  self.filenames = filenames
  self.num_epochs = num_epochs
