def __init__(self, wall_time, locator, op_type, op_name, output_slot,
             graph_id):
  super().__init__(wall_time, locator)
  self._op_type = op_type
  self._op_name = op_name
  self._output_slot = output_slot
  self._graph_id = graph_id


