def predict(self,
            model,
            x,
            batch_size=None,
            verbose=0,
            steps=None,
            callbacks=None,
            **kwargs):
  batch_size = model._validate_or_infer_batch_size(batch_size, steps, x)
  x, _, _ = model._standardize_user_data(
      x, check_steps=True, steps_name='steps', steps=steps)
  return predict_loop(
      model,
      x,
      batch_size=batch_size,
      verbose=verbose,
      steps=steps,
      callbacks=callbacks)

